const _enc=new TextEncoder();

const response = $input.first().json;
const records = response.records || [];

if (records.length === 0) {
  return [{ json: { _auth_error: true, message: 'Invalid email or password' } }];
}

const user = records[0];
const fields = user.fields || {};

const storedValue = fields.password_hash || fields.password || '';
const inputPassword = $('Extract Credentials').first().json.password;

let passwordValid = false;
if (storedValue.includes(':')) {
  const [salt, hash] = storedValue.split(':');
  const inputHash = sha256Hex(salt + inputPassword);
  passwordValid = (inputHash === hash);
} else {
  passwordValid = (storedValue === inputPassword);
}

if (!passwordValid) {
  return [{ json: { _auth_error: true, message: 'Invalid email or password' } }];
}

const JWT_SECRET = 'cosmisk-jwt-secret-2026-v1';

const header = Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })).toString('base64url');
const payload = Buffer.from(JSON.stringify({
  sub: user.id,
  email: fields.email,
  role: fields.role || 'client',
  name: fields.name || fields.full_name || '',
  iat: Math.floor(Date.now() / 1000),
  exp: Math.floor(Date.now() / 1000) + (24 * 60 * 60)
})).toString('base64url');

const signature = b64url(hmacSHA256(_enc.encode(JWT_SECRET), _enc.encode(header + '.' + payload)));
const token = header + '.' + payload + '.' + signature;

return [{
  json: {
    _auth_error: false,
    token,
    user: {
      id: user.id,
      name: fields.name || fields.full_name || '',
      email: fields.email,
      role: fields.role || 'client',
      onboardingComplete: true,
      plan: fields.plan || 'starter',
      createdAt: fields.created_at || user.createdTime
    }
  }
}];
